//! Minimal re-implementation of the `tsl::hopscotch_map` interface used by
//! the test program, backed by the standard library's hash table.
//!
//! Only the operations exercised by `test1.cpp` are provided:
//! `new`, `insert` and `size`.

use std::collections::HashMap;
use std::hash::Hash;

/// A hash map with the same observable behaviour as
/// `tsl::hopscotch_map<K, V>` for the operations used here.
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K: Eq + Hash, V> HopscotchMap<K, V> {
    /// Creates an empty map.
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    /// Inserts a key/value pair. If the key already exists, the stored
    /// value is kept (matching `tsl::hopscotch_map::insert`, which does
    /// not overwrite on duplicate keys).
    pub fn insert(&mut self, key: K, value: V) {
        self.inner.entry(key).or_insert(value);
    }

    /// Returns the number of elements in the map.
    pub fn size(&self) -> usize {
        self.inner.len()
    }
}

impl<K: Eq + Hash, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

