mod hopscotch_map;

use hopscotch_map::HopscotchMap;

/// Mimics C++ `std::stoi`: skips leading whitespace, accepts an optional
/// sign, then parses the longest run of decimal digits.
fn stoi(s: &str) -> i32 {
    let trimmed = s.trim_start();
    let (sign, digits) = match trimmed.strip_prefix('-') {
        Some(rest) => (-1i64, rest),
        None => (1i64, trimmed.strip_prefix('+').unwrap_or(trimmed)),
    };
    let mut value: i64 = 0;
    let mut any = false;
    for c in digits.chars() {
        if let Some(d) = c.to_digit(10) {
            value = value * 10 + d as i64;
            any = true;
        } else {
            break;
        }
    }
    if !any {
        panic!("stoi: no conversion");
    }
    (sign * value) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut count: i32 = 1;
    if args.len() > 1 && args[1] == "--a" {
        count = stoi(&args[2]);
    }

    let mut map: HopscotchMap<i32, String> = HopscotchMap::new();
    for i in 0..count {
        map.insert(i, format!("value{}", i));
    }

    println!("{}", map.size());
}

